import{_ as s,c as a,a as n,o as i}from"./app-C_dHcy8Q.js";const t={};function o(c,e){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="metrics-observability" tabindex="-1"><a class="header-anchor" href="#metrics-observability"><span>Metrics &amp; Observability</span></a></h1><p>This doc lists the built-in metrics endpoints and exported series for Server/Agent/Edge.</p><p>Endpoints</p><ul><li>JSON metrics <ul><li>Server: GET /metrics</li><li>Agent: GET /metrics</li><li>Edge: GET /metrics</li></ul></li><li>Prometheus text format <ul><li>Server: GET /metrics.prom</li><li>Agent: GET /metrics.prom</li><li>Edge: GET /metrics.prom</li></ul></li></ul><p>Server JSON (/metrics)</p><ul><li>uptime_sec</li><li>invocations_total / invocations_error_total</li><li>jobs_started_total / jobs_error_total</li><li>rbac_denied_total / audit_errors_total</li><li>logs: <code>{ debug, info, warn, error, total }</code></li><li>lb_stats, conn_pool (when available)</li><li>functions: per-function snapshot <ul><li>invocations_total / errors_total / rbac_denied_total</li><li>latency_seconds: <code>{ buckets[], counts[], sum, count }</code></li></ul></li></ul><p>Server Prometheus (/metrics.prom)</p><ul><li>croupier_invocations_total</li><li>croupier_invocations_error_total</li><li>croupier_jobs_started_total</li><li>croupier_jobs_error_total</li><li>croupier_rbac_denied_total</li><li>croupier_audit_errors_total</li><li><code>croupier_logs_total{level=&quot;debug|info|warn|error&quot;}</code></li><li>Per-function series <ul><li><code>croupier_invocations_total{function_id=&quot;...&quot;}</code></li><li><code>croupier_invocations_error_total{function_id=&quot;...&quot;}</code></li><li><code>croupier_rbac_denied_total{function_id=&quot;...&quot;}</code></li><li><code>croupier_invoke_latency_seconds_bucket{function_id=&quot;...&quot;,le=&quot;...&quot;}</code></li><li><code>croupier_invoke_latency_seconds_sum{function_id=&quot;...&quot;}</code></li><li><code>croupier_invoke_latency_seconds_count{function_id=&quot;...&quot;}</code></li></ul></li></ul><p>Agent JSON (/metrics)</p><ul><li>functions, instances, tunnel_reconnects</li><li>logs</li></ul><p>Agent Prometheus (/metrics.prom)</p><ul><li><code>croupier_agent_instances</code></li><li><code>croupier_tunnel_reconnects</code></li><li><code>croupier_logs_total{level}</code></li></ul><p>Edge JSON (/metrics)</p><ul><li>tunnel metrics map + logs</li></ul><p>Edge Prometheus (/metrics.prom)</p><ul><li><code>croupier_logs_total{level}</code></li></ul><p>Notes</p><ul><li>Histogram buckets follow Prometheus defaults (0.005 .. 10 seconds). Values are best-effort for HTTP path and meant for dashboards/alerts.</li><li>Series cardinality: per-function metrics may increase cardinality; keep function ids bounded.</li><li>Toggles: you can disable per-function metrics via <code>--metrics.per_function=false</code> and enable per-game RBAC denied counters via <code>--metrics.per_game_denies=true</code>.</li></ul><p>Prometheus scrape example</p><div class="language-yaml line-numbers-mode" data-highlighter="prismjs" data-ext="yml"><pre><code class="language-yaml"><span class="line"><span class="token key atrule">scrape_configs</span><span class="token punctuation">:</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">job_name</span><span class="token punctuation">:</span> <span class="token string">&#39;croupier-server&#39;</span></span>
<span class="line">    <span class="token key atrule">metrics_path</span><span class="token punctuation">:</span> /metrics.prom</span>
<span class="line">    <span class="token key atrule">static_configs</span><span class="token punctuation">:</span> <span class="token punctuation">[</span> <span class="token punctuation">{</span> <span class="token key atrule">targets</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&#39;localhost:8080&#39;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">job_name</span><span class="token punctuation">:</span> <span class="token string">&#39;croupier-agent&#39;</span></span>
<span class="line">    <span class="token key atrule">metrics_path</span><span class="token punctuation">:</span> /metrics.prom</span>
<span class="line">    <span class="token key atrule">static_configs</span><span class="token punctuation">:</span> <span class="token punctuation">[</span> <span class="token punctuation">{</span> <span class="token key atrule">targets</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&#39;localhost:19091&#39;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">]</span></span>
<span class="line">  <span class="token punctuation">-</span> <span class="token key atrule">job_name</span><span class="token punctuation">:</span> <span class="token string">&#39;croupier-edge&#39;</span></span>
<span class="line">    <span class="token key atrule">metrics_path</span><span class="token punctuation">:</span> /metrics.prom</span>
<span class="line">    <span class="token key atrule">static_configs</span><span class="token punctuation">:</span> <span class="token punctuation">[</span> <span class="token punctuation">{</span> <span class="token key atrule">targets</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&#39;localhost:9080&#39;</span><span class="token punctuation">]</span> <span class="token punctuation">}</span> <span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Grafana quick panel ideas</p><ul><li>Query rate by function: <code>increase(croupier_invocations_total{function_id=&quot;$fid&quot;}[5m])</code></li><li>Error ratio: <code>increase(croupier_invocations_error_total{function_id=&quot;$fid&quot;}[5m]) / increase(croupier_invocations_total{function_id=&quot;$fid&quot;}[5m])</code></li><li>P95 latency: <code>histogram_quantile(0.95, sum by (le,function_id) (rate(croupier_invoke_latency_seconds_bucket[5m])))</code></li></ul>`,22)])])}const r=s(t,[["render",o]]),p=JSON.parse(`{"path":"/metrics.html","title":"Metrics & Observability","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1763326585000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":5,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"4651abc2dc4ea79d9d7986013ce873f113d7383f","time":1763326585000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(analytics): add ClickHouse schema + example queries; link from overview\\\\ndocs(metrics,ops): publish pages and escape MDX-sensitive tokens\\\\ndocs(sdk): add JS signature example"},{"hash":"0ac3783c0cafbb7e76dd3fb0484cad90c77386b8","time":1763325744000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs(analytics): fix unresolved links; add missing pages; harden MDX; CI link check\\\\n\\\\nfeat(analytics): add public ingestion service (cmd/analytics-ingest), Makefile targets, Dockerfiles; compose service; fix worker image\\\\n\\\\nchore(docs): adjust config to ignore node_modules in docs plugin; remove duplicate index page\\\\n\\\\nrefactor(docs): escape MDX-sensitive chars and fence YAML blocks"},{"hash":"8644ff904a38aea858fa94f2bae89da4948f527b","time":1761967259000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"feat(packs): add type registry and transport-aware encode/decode (proto JSON&#x3C;->pb-bin) in HTTP; preload FDS from descriptors; add /api/packs/import and CLI 'croupier packs import'"},{"hash":"de61c861f1d3bf6f672de59a5a952b7e6f56e500","time":1761966883000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"feat(metrics): add per-function histograms with approx p50/p95/p99, toggles (--metrics.per_function, --metrics.per_game_denies); expose in JSON and when enabled in Prom text; wire toggles in CLI"},{"hash":"9f207cce9eb1f95a1378152046c1bc159d54c783","time":1761966594000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs: add metrics.md (JSON+Prometheus endpoints and series) and config.md (includes/profiles precedence)"}]},"filePathRelative":"metrics.md"}`);export{r as comp,p as data};
